import {World} from './world.mjs';
import {KEY,RELEASE,CHAPTERS,LO1,LO2,initial,enter,begin,keyFor,validInput,investigationReady,explainInvestigation,submit,retry,guided,advance,trial,finishExplore,results,solve,predicted,setImage,constructIntersection,startBonus,acknowledgeRecap,continueJourney,endingFeedback} from './game.mjs';
import {length,ghost,optimal} from './math.mjs';
import {viewerPath,viewerHint,traceNetwork,snapPoint,inspectPath} from './mechanics.mjs';
import {LEARNING,BONUS_LEARNING} from './learning.mjs';
import {has,stage,worldGoal,pendingAction,performAction,passStatus} from './journey.mjs';
import {opening,mapPanel,pendingPanel,rewardLine} from './story-ui.mjs';
import {isFinalConstruction,constructionPrompts,toggleConstructionHint,constructionHint} from './construction.mjs';
const ui=document.querySelector('#ui');let s=initial(),storageWarning=false;try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw?.version===4&&raw.settings&&raw.choices&&Array.isArray(raw.history))s={...s,...raw};}catch{storageWarning=true;}
let world,busy=false,draftFrame=null,modal='',helpStep=0,helpTimer=null,lessonTimer=null,notice='',motionLabel='',audio;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,act,cls='primary',extra='')=>`<button type="button" data-action="${act}" class="${cls}" ${extra}>${text}</button>`;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storageWarning=true;}};
const LESSONS=[null,
 [['Reflection and light paths','Reflection is a change of light’s direction at a mirror. An opaque wall blocks light. Light from the scene reaches mirror 2, mirror 1, then the eye.'],['Build, then turn','Fit both mirrors. Aim the backward guide from mirror 1 to mirror 2, then towards the gallery window. Light can follow that same path in reverse.'],['Check what the view demonstrates','The two finite mirrors provide a clear viewing path around the wall. Read Lumi and Pip’s arcade passage sign, then confirm the view.']],
 [['The law of reflection','A normal is a line perpendicular to a surface: a right angle of 90°. Incidence is the incoming angle; reflection is the outgoing angle. Measure both from the normal.'],['See why the angles match','In this separate example the incoming angle is 40°, so the outgoing angle is 40° on the other side of the normal. The source and reflected paths stay on the same side of the surface.'],['Apply it to an ideal bank shot','Our toy ball’s centre follows this ideal reflection rule without spin. Predict and catch two shots to release the arcade passage. Launch records your first prediction.']],
 [['Reflection symmetry','The crease is the mirror line. Each reflected partner belongs on the opposite side, at equal perpendicular distance—straight across at 90°.'],['See the fold','In this separate example, the source is 3 units from the crease. Its partner is 3 units across it. A perpendicular guide keeps their left/right positions aligned.'],['Use the visible grid','Every small square is 0.5 units; bottom numbers count left/right units. Stamps snap to every grid point, including wrong ones. Select a colour and drag its partner; compare the two rulers.'],['Fold to check your prediction','Place all three partners, then fold to check the visitor pass. The measured ink positions appear after commitment. The grid removes fine mouse precision. Negative values indicate the near side of the crease; positive values indicate the far side.']],
 [['Investigate a reflected light path','A is a light source, B is a receiver, and the blue line is one fixed flat mirror. Predict which proposed bounce will send light to B.'],['Compare proposal with reality','A dashed A–P–B route is a proposal. When tested, the solid beam always obeys equal-angle reflection. A wrong proposal misses B.'],['Connect reflection and path length','Here the successful equal-angle path also has the shortest one-reflection length. One successful test lets you explain why. You can compare other bounces if you want; the construction in the next room shows why this path is shortest.']],
 [['Reflection construction with B′','B′, pronounced B prime, is B reflected across the mirror: the same perpendicular distance on the opposite side. Reuse the folded-pass grid skill. In this plan, negative distance lies behind the mirror.'],['Draw your straightedge','Choose B′ on the half-unit grid, then draw the line from A to your chosen point. Your tool does not supply the correct B′.'],['Construct an intersection','An intersection is where two objects meet. Use Mark P to intersect your A–B′ line with the mirror. No fine clicking or numeric estimate of P is needed.'],['Why this gives the shortest path','For every P on the mirror, PB = PB′. A straight A–B′ connection makes the corresponding A–P–B path shortest. Editing B′ clears the old line and P.']],
 [['Review and Apply','This final mission uses familiar methods: two direction predictions with the equal-angle rule, then one new reflection construction. There is no new mathematical rule.'],['Choose the learned method','Use a method you practised for each new device. The final construction keeps its tools available, with an optional Hint if you want a method reminder. No new mathematical rule is needed. The optional workshop comes after you both leave the museum.']],
 [['Optional mirror design workshop','This is an extra design challenge outside the six tasks and their LO scores. Select, place and turn mirrors to route light around a wall.'],['Test and revise a design','Each mirror follows the same reflection law. The tested beam shows the first place a design stops. Try a new arrangement; up to three mirrors are available.'],['Several designs can work','A valid beam reaches the receiver without crossing the wall. A working arrangement is not a claim of global shortest distance. Return outside whenever you choose.']]
];
const focusFor=()=>s.bonus?BONUS_LEARNING:LEARNING[s.chapter];
const lessonSteps=()=>LESSONS[s.bonus?7:s.chapter];
function about(){const resume=!!s.task;return `<section class="about"><div class="about-card"><p class="kicker">A SIX-ROOM 3D STEM ADVENTURE · v${RELEASE}</p><h1>FIND<br><span>LUMI!</span></h1><p class="tagline">A little reflection. A big reunion.</p><p>You’re Maya. Your child Lumi is safe with Pip in the mirror museum. Open a route through the exhibits, repair a visitor pass and reach Lumi. Then use reflection to leave the museum together.</p><p><strong>Game goal:</strong> reach Lumi in the Star Gallery, then leave the museum together.</p><div class="about-actions">${button(resume?'Continue adventure →':'Start all 6 tasks →',resume?'resume':'start')}${resume?button('New adventure','reset','quiet'):''}</div><div class="about-info"><strong>ABOUT THE GAME</strong><p><b>Topic:</b> shortest paths and reflection.<br><b>Primary STEM branch:</b> Mathematics.<br><b>Integrated branches:</b> Science — optics and ideal bounces; optional Engineering — mirror design.</p><p>For junior secondary learners and beginner adults. No engineering, trigonometry or proof knowledge required. Worked examples introduce each operation before play. Angles, normals and symmetry are introduced inside the game.</p><p><strong>Educational goal:</strong> use reflection and symmetry to predict light paths and construct shortest routes.</p><h2>Two learning outcomes</h2><p><b>LO1 · Predict</b><br>${LO1}</p><p><b>LO2 · Construct</b><br>${LO2}</p><details><summary>How the game teaches · strategies and evidence</summary><p>Guided discovery; captioned worked examples; visual feedback; guided practice; an optional method reminder in the final construction; fresh recovery and transfer checks. LO1’s four first predictions occur in Rooms 2 (ideal ball bounces) and 6 (light). LO2’s three first constructions occur in Rooms 5 and 6. Completion with support is recorded separately.</p><p><b>Factual:</b> labelled normals, angles and coordinates. <b>Conceptual:</b> equal angles and equal perpendicular distances. <b>Procedural:</b> reflect, connect, then mark the crossing. <b>Problem solving:</b> compare full journeys and apply the construction to new layouts.</p><p><b>ABCD:</b> A = junior secondary or beginner adult learners. LO1: B = predict; C = four specified ideal reflection scenarios; D = at least 3/4 first predictions within ±3°. LO2: B = construct; C = three source–receiver diagrams with construction tools; D = at least 2/3 first constructions, both points within 0.15 units and a connecting line.</p></details><p class="small">About 25–35 minutes is a planning estimate. Save and pause anytime. Beginner suitability and engagement still need learner playtesting.</p><div class="links">${button('Accessibility','settings','text')}${button('Credits & reference','credits','text')}</div></div></div><div class="cover-sticker"><span>6 ROOMS</span><strong>FIND HER.<br>LEAVE TOGETHER.</strong><small>Everything you need<br>is taught inside.</small></div></section>`;}
function hud(){const c=CHAPTERS[s.chapter-1];return `<header class="hud"><div class="logo">FIND LUMI!<small>${s.bonus?'OPTIONAL MIRROR WORKSHOP':'MIRROR MUSEUM'}</small></div><button type="button" class="progress" data-action="map" aria-label="Open the museum route map"><strong>${s.bonus?'OPTIONAL':`TASK ${s.chapter} / 6 · MAP`}</strong><div>${(s.bonus?[]:CHAPTERS).map((_,i)=>`<i class="${s.completed.includes(i+1)?'done':s.chapter===i+1?'active':''}" title="Task ${i+1}"></i>`).join('')}</div></button><div class="hud-actions">${s.bonus?button('Outside','exit-bonus','quiet'):''}${button('? Help','help','quiet')}${button('Pause','menu','quiet')}</div></header><div class="objective"><span>${s.bonus?'OPTIONAL EXTENSION':c[2].toUpperCase()} ${subLabel()}</span><h1>${s.bonus?'Design a mirror link':c[0]}</h1><p>${objectiveText()}</p></div><div class="room-controls">${button(s.inspection?'Look around room':'Inspect the activity · E','view','quiet')}${s.inspection?'':'<span>Drag to look · WASD to move · E to inspect</span>'}</div>${s.task.kind==='viewer'&&s.inspection&&s.phase!=='lesson'?`<div class="viewer-window"><strong>VIEWER WINDOW · TWO REFLECTIONS</strong><span id="viewer-status">${viewerHint(s.task,s.draft)}</span></div>`:''}`;}
function subLabel(){if(s.bonus)return '· OUTSIDE LO SCORES';if(s.chapter===2)return `· SHOT ${s.sub+1}/2`;if(s.chapter===5)return `· CONSTRUCTION ${s.sub+1}/2`;if(s.chapter===6)return `· ${s.sub<2?`DIRECTION ${s.sub+1}/2`:'CONSTRUCTION'}`;return '';}
function objectiveText(){return `${worldGoal(s)}<span class="learning-focus">You are learning: ${focusFor().concept}.</span>`;}
function slider(id,label,value,min,max,step=1){return `<label class="slider-label" for="${id}"><span>${label}</span><output id="${id}-output">${Number(value).toFixed(step<1?1:0)}${['rotation','rotation2','mirror-rotation','angle'].includes(id)?'°':''}</output></label><input id="${id}" type="range" value="${value}" min="${min}" max="${max}" step="${step}" ${busy?'disabled':''}>`;}
function inputs(){const t=s.task,d=s.draft;
 if(t.kind==='viewer')return `<div class="build-kit">${[0,1].map(i=>button(d.installed[i]?`✓ Mirror ${i+1}`:`Fit mirror ${i+1}`,`install-${i}`,d.installed[i]?'selected':'quiet',`draggable="true" data-part="${i}"`)).join('')}</div><p class="hint">Fit both mirrors, then turn each one. Watch the live viewer window.</p>${slider('rotation','Mirror 1 orientation',d.angles[0],0,180,.5)}${slider('rotation2','Mirror 2 orientation',d.angles[1],0,180,.5)}`;
 if(t.kind==='ray')return `<div class="given"><b>GIVEN PATH</b> Incoming angle: <strong>${t.angle}° from the normal</strong>.</div><div class="play-instruction">${s.chapter===2?'Drag the purple catcher. Then launch the ball.':'Drag the purple receiver. Then send the light.'}</div><details class="precision"><summary>Precision controls · keyboard alternative</summary>${slider('angle','Your outgoing angle · from the normal',d.angle,0,85)}<div class="inline-options">${button('Across the normal','side-right',d.side===1?'selected':'quiet')}${button('Same side','side-wrong',d.side===-1?'selected':'quiet')}</div></details><p class="hint">Purple is your prediction. The actual path appears after launch. Allowance ±3°.</p>`;
 if(t.kind==='shape'){const p=d.points[d.selected];return `<div class="piece-picker" aria-label="Choose an ink stamp">${['Red','Blue','Purple'].map((name,i)=>button(`${i+1} · ${name}`,`piece-${i}`,d.selected===i?'selected':'quiet')).join('')}</div><div class="play-instruction">Drag this ink partner across the crease.</div><p class="hint" id="placed-count">${d.parts?.filter(Boolean).length||0}/3 partners placed · chosen ${s.choices.art} pass</p><p class="grid-rule">0.5-unit grid · opposite side · equal perpendicular distance</p><details class="precision"><summary>Coordinates & precision controls</summary><div class="given"><b>GIVEN ${['RED','BLUE','PURPLE'][d.selected]}</b> x = ${t.source[d.selected].x.toFixed(1)} · ${t.source[d.selected].y.toFixed(2)} units on the far side.</div>${slider('point-x','Stamp left / right',p.x,0,10,.5)}${slider('point-y','Stamp across the crease',p.y,-3.5,3.5,.5)}</details><p class="hint">Folding checks the pass’s reflected pattern after your plan is committed.</p>`;}
 if(t.kind==='network'){const m=d.mirrors[d.selected];return `<div class="given"><b>FIXED SOURCE</b> Light starts ${t.direction.x>0?'towards the right →':'towards the left ←'}. The wall is opaque.</div><div class="piece-picker">${d.mirrors.map((_,i)=>button('Mirror '+(i+1),`mirror-${i}`,d.selected===i?'selected':'quiet')).join('')}${d.mirrors.length<3?button('+ Third','add-mirror','quiet'):''}</div><div class="play-instruction">Drag the selected mirror onto the floor.</div><div class="turn-buttons">${button('↶ −5°','turn-left','quiet')}${button('↷ +5°','turn-right','quiet')}<output id="mirror-angle">${m.angle.toFixed(1)}°</output></div><p class="hint" id="placed-count">${d.mirrors.filter(m=>m.placed).length} mirrors placed · up to 3 allowed</p><details class="precision"><summary>Position & precision controls</summary>${slider('point-x','Mirror left / right',m.x,0,10,.1)}${slider('point-y','Mirror near / far',m.y,-3.5,3.5,.1)}${slider('mirror-rotation','Mirror orientation',m.angle,0,180,.5)}</details><p class="hint">Several layouts can work. Test to reveal the beam and its stopping point.</p>`;}
 const prompts=constructionPrompts(s);
 return `<div class="given"><b>RECEIVER B</b> x = ${t.b.x.toFixed(1)} · ${t.b.y.toFixed(1)} units in front of the mirror.</div><div class="inline-options">${button(prompts.place,'mode-image',d.mode==='image'?'selected':'quiet')}${button(prompts.line,'line',d.line?'selected':'quiet')}${button(prompts.intersect,'intersect',d.intersection?'selected':'quiet')}</div><div class="play-instruction">${prompts.instruction}</div>${d.intersection?`<div class="construction-readout">P ≈ (${d.p.toFixed(4)}, 0)<small>Constructed from your chosen objects.</small></div>`:''}<details class="precision"><summary>B′ grid position · keyboard alternative</summary>${slider('point-x','B′ left / right',d.image.x,0,10,.5)}${slider('point-y','B′ in front / behind',d.image.y,-4,4,.5)}</details>${constructionHint(s)}<p class="hint">All grid points snap equally. The intersection tool uses your B′, and does not correct a wrong reflection. Dashed lines are constructions; solid lines after testing are actual rays.</p>`;
}
function controls(){if(!s.inspection)return `<section class="inspect-prompt">${button('Inspect activity · E','view')}<p>Inspection gives a fixed view and accessible controls.</p></section>`;
 if(s.task.kind==='investigation'){
  const d=s.draft,t=s.task,ready=investigationReady(s),evidence=`<div class="path-measurements">${d.tests.map(r=>`<article><b>Bounce ${r.index+1} · ${r.hit?'REACHES B':'MISSES B'}</b><span>Proposed legs ${r.first.toFixed(2)} + ${r.second.toFixed(2)} · total ≈ ${r.total.toFixed(2)}</span><span>α incoming ${r.alpha.toFixed(1)}° · β needed for B ${r.beta.toFixed(1)}°</span></article>`).join('')}</div>`,choices=`<div class="candidate-picker">${t.candidates.map((p,i)=>button(`Bounce ${i+1}`,`candidate-${i}`,d.selected===i?'selected':'quiet',busy?'disabled':'')).join('')}</div>`;
  return `<section class="control-card investigation-controls"><div class="card-head"><b>${d.explaining?'2 · EXPLAIN YOUR FINDING':'1 · PREDICT AND TEST'}</b><span>${d.tests.length}/3 TESTED</span></div>${d.explaining?`<p class="play-instruction">Choose the successful bounce and explain why it works.</p>${choices}<details class="precision"><summary>Review your tested lengths and angles</summary>${evidence}</details><fieldset class="reason-picker"><legend>The successful shortest path works because…</legend>${[['equal-shortest','Its angles from the normal match, and its full one-bounce path is shortest.'],['midpoint','The midpoint of the mirror always works.'],['first-leg','Only the A–P segment needs to be short.']].map(([v,label])=>`<label><input type="radio" name="path-reason" value="${v}" ${d.reason===v?'checked':''}>${label}</label>`).join('')}</fieldset><p class="validation" id="validation" role="alert">${notice}</p>${button('Confirm & see what I learned →','submit','primary')}${button('← Test another bounce (optional)','back-investigation','text')}`:`<p class="play-instruction">Choose a bounce and trace the light. Once it reaches B, you can explain why it works.</p>${choices}${button(busy?'Tracing the actual ray…':'Trace selected bounce ▶','test-path','quiet',busy||d.selected==null?'disabled':'')}${evidence}<p class="hint">Dashed = proposed A–P–B. Solid = actual reflection. The actual outgoing angle equals α. Displayed measurements are rounded.</p>${button('Explain this path →','explain-investigation','primary',busy||!ready?'disabled':'')}<p class="hint">${ready?'B received the light. Explain now, or compare another bounce if you want.':'Find a bounce that reaches B. No extra test is required after a success.'}</p>`}${button('Watch an example','example','text')}</section>`;
 }

 const kind=s.task.kind,title={viewer:'BUILD · TURN · LOOK',ray:s.chapter===2?'AIM · LAUNCH · CATCH':'PREDICT · SEND · REVIEW',shape:'PLACE · FOLD · EXPLAIN',route:isFinalConstruction(s)?'EXIT RECEIVER · YOUR PLAN':'REFLECT · CONNECT · INTERSECT',network:'OPTIONAL · DESIGN · TEST'}[kind],label={viewer:'Look through my viewer →',ray:s.chapter===2?'Launch bank shot ▶':'Send gallery light ▶',shape:'Fold & check my pass →',route:'Send my constructed path ▶',network:'Test my mirror design ▶'}[kind];
 return `<section class="control-card ${kind}-controls${isFinalConstruction(s)?' final-construction':''}"><div class="card-head"><b>${title}</b>${s.variant?`<span>FRESH LAYOUT ${s.variant+1}</span>`:''}</div>${inputs()}<p class="validation" id="validation" role="alert">${notice}</p>${button(label,'submit','primary')}<div class="card-footer">${button('Watch an example','example','text')}<span>${kind==='route'?'Intersection tool · no fine clicking':'Take your time'}</span></div></section>`;
}
function result(){const r=s.result,ok=r.ok,t=s.task;let message=r.message;if(ok&&t.kind==='ray')message=`The model outgoing angle is ${t.angle}°, equal to the incoming angle from the normal. Your ${s.draft.angle}° prediction is within the ±3° allowance.`;if(ok&&t.kind==='route')message='Your chosen B′ is the reflected destination. The intersection of A–B′ and the mirror gives the required one-bounce path.';return `<section class="result-card ${ok?'good':'repair'}" tabindex="-1"><p class="kicker">${busy?'WATCH THE COMMITTED RESULT':ok?r.guided?'COMPLETED WITH SUPPORT':'COMPARE WITH THE RULE':'A CLUE FOR YOUR NEXT TRY'}</p><h2>${ok?'See why it works.':'Let’s repair the plan.'}</h2><p>${message}</p>${!ok?`<p class="small">${t.kind==='network'?'The stopped ray diagnoses this design.':t.kind==='viewer'?'Use the guide to align the two reflections.':t.kind==='investigation'?'The next attempt changes the source–receiver layout.':'The committed result is shown. A retry uses a changed layout.'}</p>`:''}<div class="result-actions">${ok?button(nextText(),'advance','primary',busy?'disabled':''):button('Try a fresh layout →','retry','primary',busy?'disabled':'')}${!ok?button('Watch the method','example','quiet'):''}${!ok&&s.errors>=2?button('Complete together with Pip','guided','quiet',busy?'disabled':''):''}</div></section>`;}
function nextText(){if(s.chapter===2&&s.sub===0)return 'Apply the rule to shot 2 →';if(s.chapter===5&&s.sub===0)return 'Approach lit · open the gallery gate →';if(s.chapter===6)return s.sub===0?'Follow return marker 1 →':'Follow marker 2 · open the exit →';return 'Continue →';}
function complete(){if(pendingAction(s))return pendingPanel(s);const l=focusFor();return `<dialog id="learning-recap" class="learning-recap" aria-labelledby="recap-title"><p class="kicker">${s.bonus?'OPTIONAL WORKSHOP COMPLETE':`TASK ${s.chapter} OF 6 COMPLETE`}${s.chapterGuided?' · WITH PIP’S SUPPORT':''}</p><h2 id="recap-title" tabindex="-1">${s.chapterGuided?l.supported:l.action}</h2><p class="world-reward">${rewardLine(s)}</p><p class="recap-concept"><b>Concept:</b> ${l.concept}</p><p>${l.why}</p><p class="recap-next">${l.next}</p><div class="result-actions">${button(s.bonus?'Back outside →':s.chapter===6?'Outside together →':['','Follow the arcade passage →','Enter the pass studio →','Step into the courtyard →','Approach the gallery gate →','Leave with Lumi →'][s.chapter],'next')}${button('Show this idea again','example','quiet')}${button('Route map','map','text')}</div></dialog>`;}
function motionCard(){return `<section class="motion-status" role="status"><b>${motionLabel||(s.task.kind==='shape'?'Folding and checking the pass…':'Watch what your action changes…')}</b><span>The learning explanation follows this animation.</span></section>`;}
function ending(){const r=results(s);return `<header class="hud"><div class="logo">FIND LUMI!<small>ALL 6 TASKS COMPLETE</small></div>${button('Help & settings','settings','quiet')}</header><section class="ending"><p class="kicker">THE MUSEUM EXIT · OUTSIDE TOGETHER</p><h1>“We made it<br><span>out together!”</span></h1><p>You found the passage, used your repaired visitor pass, reached Lumi and guided her out of the museum. Lumi stayed safe with Pip throughout. Both Maya and Lumi have reached the exit.</p><h2 class="ending-feedback">${endingFeedback(r)}</h2><div class="report-summary"><article><span>LO1 · PREDICT</span><strong>${r.rays}/4</strong><small>${r.rays>=3?'Target demonstrated independently':'Next target: 3/4 independent first answers'}</small></article><article><span>LO2 · CONSTRUCT</span><strong>${r.routes}/3</strong><small>${r.routes>=2?'Target demonstrated independently':'Next target: 2/3 independent first answers'}</small></article></div><p class="small">${r.recovered} fresh recovery successes · ${r.guided} guided completions. Original first results are preserved. Finishing with help is different from independent mastery.</p><div class="result-actions">${button('My learning record','report')}${button('Download results','download','quiet')}${button('Review concepts','concepts','quiet')}${button('Optional mirror workshop','bonus','quiet')}${button('New adventure','reset','quiet')}</div></section>`;}
function methodType(){if(s.bonus)return 7;if(s.chapter===6)return s.sub<2?2:5;return s.chapter;}
function lessonSVG(n,step){if(n===1||n===7)return `<svg viewBox="0 0 360 210" role="img" aria-label="Separate two-mirror example"><rect width="360" height="210" rx="12" fill="#deece6"/><rect x="145" y="30" width="70" height="100" rx="5" fill="#c3a7c6"/><path d="M65 180V150H290V45" fill="none" stroke="#e3ae5e" stroke-width="4"/><path d="M40 175L90 125M265 175L315 125" stroke="#78b4bc" stroke-width="8"/><text x="30" y="198">eye / source</text><text x="269" y="30">scene / target</text><text x="163" y="80">wall</text><text x="85" y="142">1</text><text x="313" y="143">2</text></svg>`;if(n===3)return `<svg viewBox="0 0 360 220" role="img" aria-label="Separate folding example showing equal perpendicular distances"><rect width="360" height="220" rx="12" fill="#f3ebdc"/><path d="M25 110H335" stroke="#d4a342" stroke-width="5"/><path d="M90 35V185" stroke="#8e82a5" stroke-dasharray="5 5"/><path d="M90 95H105V110" stroke="#8e82a5" fill="none"/><circle cx="90" cy="50" r="8" fill="#d58e76"/><text x="105" y="47">source</text><text x="35" y="83">3 units</text>${step>0?'<circle cx="90" cy="170" r="8" fill="#72b39e"/><text x="105" y="174">reflected partner</text><text x="35" y="148">3 units</text>':''}<text x="220" y="103">mirror line</text><text x="90" y="207">Equal perpendicular distances</text></svg>`;if(n===4)return `<svg viewBox="0 0 360 220" role="img" aria-label="Separate example: a proposed path and the equal-angle reflection"><rect width="360" height="220" rx="12" fill="#e5eee5"/><path d="M25 110H335" stroke="#78afb7" stroke-width="7"/><circle cx="70" cy="55" r="7" fill="#d5a64f"/><text x="52" y="42">A</text><circle cx="275" cy="35" r="7" fill="#9b81b5"/><text x="286" y="35">B</text><path d="M70 55L220 110L275 35" stroke="#ba987a" stroke-dasharray="6 5" fill="none"/><text x="233" y="142">proposal</text>${step>0?'<path d="M70 55L156.7308 110L275 35" stroke="#4aab95" stroke-width="4" fill="none"/><path d="M156.7308 20V150" stroke="#6d8bab" stroke-dasharray="5 4"/><text x="163" y="25">normal</text>':''}<text x="35" y="190">Both segments count: A–P + P–B</text></svg>`;if(n===2){const out=step>0?'<path d="M180 145L270 38" stroke="#53a997" stroke-width="4" fill="none"/><text x="222" y="85">40°</text>':'';return `<svg viewBox="0 0 360 210" role="img" aria-label="Separate worked reflection example"><rect width="360" height="210" rx="12" fill="#e1eff0"/><path d="M70 145H290" stroke="#6a87a1" stroke-width="8"/><path d="M180 20V175" stroke="#6b8b9b" stroke-dasharray="6 5"/><path d="M180 130H195V145" stroke="#6b8b9b" fill="none"/><path d="M90 38L180 145" stroke="#dda049" stroke-width="4" fill="none"/><text x="109" y="85">40°</text><text x="190" y="25">normal</text>${out}</svg>`;}const showImage=n===3||n===5&&step>=0,showLine=n===5&&step>=1,showP=n===5&&step>=2;return `<svg viewBox="0 0 360 220" role="img" aria-label="Separate symmetry and route example"><rect width="360" height="220" rx="12" fill="#eee7f3"/><path d="M30 110H330" stroke="#d4a342" stroke-width="6"/><circle cx="70" cy="55" r="7" fill="#a386b9"/><text x="53" y="43">A</text><circle cx="275" cy="35" r="7" fill="#bd8c43"/><text x="287" y="35">B</text>${showImage?'<path d="M275 35V185" stroke="#9d8ab0" stroke-dasharray="5 5"/><circle cx="275" cy="185" r="7" fill="#9b7ebc"/><text x="287" y="190">B′</text><text x="287" y="78">3</text><text x="287" y="152">3</text>':''}${showLine?'<path d="M70 55L275 185" stroke="#609fa2" stroke-width="3"/>':''}${showP?'<circle cx="156.7" cy="110" r="7" fill="#42988c"/><path d="M70 55L156.7 110L275 35" stroke="#409a8b" stroke-width="3" fill="none"/><text x="163" y="135">P</text>':''}${n===4?'<path d="M70 55L220 110L275 35" stroke="#dc9657" stroke-width="3" fill="none"/><text x="222" y="134">P</text><text x="35" y="190">Total = A–P + P–B</text>':''}</svg>`;}
function lessonPanel(){const steps=lessonSteps(),[title,copy]=steps[s.lesson],l=focusFor();return `<section class="lesson-card" aria-label="Guided demonstration"><div class="lesson-top"><span>YOU ARE LEARNING · ${l.concept.toUpperCase()}</span>${button('▶ Play','lesson-play','text')}${button('↺ Replay','lesson-replay','text')}</div><div class="lesson-body">${lessonSVG(s.bonus?7:s.chapter===6?methodType():s.chapter,s.lesson)}<div><h2>${title}</h2><p>${copy}</p>${s.lesson===0&&l.terms?`<dl class="term-list">${l.terms.map(([term,meaning])=>`<dt>${term}</dt><dd>${meaning}</dd>`).join('')}</dl>`:''}</div></div>${s.chapter===3&&s.lesson===0?`<div class="sign-choice"><p class="hint"><b>Choose your visitor pass decoration.</b> Decoration only; both designs use the same reflection task.</p><div class="inline-options">${button(s.choices.art==='star'?'✓ Star design':'Star design','art-star',s.choices.art==='star'?'selected':'quiet',`aria-pressed="${s.choices.art==='star'}"`)}${button(s.choices.art==='flower'?'✓ Flower design':'Flower design','art-flower',s.choices.art==='flower'?'selected':'quiet',`aria-pressed="${s.choices.art==='flower'}"`)}</div></div>`:''}<div class="lesson-bottom">${s.lesson>0?button('Back','lesson-back','quiet'):''}${s.lesson<steps.length-1?button('Next idea →','lesson-next'):button('Let me try! →','begin')}</div></section>`;}
function render(){const focused=document.activeElement?.id;document.body.classList.toggle('large',s.settings.large);document.body.classList.toggle('reduced',s.settings.reduced);ui.innerHTML=s.screen==='about'?about():s.screen==='opening'?opening():s.screen==='end'?ending():hud()+(s.phase==='lesson'?lessonPanel():s.phase==='complete'?(busy?motionCard():complete()):s.phase==='result'?result():controls());ui.insertAdjacentHTML('beforeend',`<dialog id="modal"><button class="close" data-action="close" aria-label="Close">×</button><div id="modal-body"></div></dialog>${storageWarning?'<div class="save-warning" role="status">Browser save is unavailable. Keep this tab open and download your report.</div>':''}`);if(focused)document.getElementById(focused)?.focus({preventScroll:true});const recap=document.querySelector('#learning-recap');if(recap){recap.addEventListener('cancel',e=>e.preventDefault());recap.showModal();recap.querySelector('#recap-title').focus();}document.querySelector('#modal').addEventListener('cancel',()=>{clearInterval(helpTimer);modal='';});save();}
function refresh(rebuild=false){if(draftFrame){cancelAnimationFrame(draftFrame);draftFrame=null;}render();if(world){rebuild?world.setup(s):world.update(s);}document.querySelector('.result-card')?.focus({preventScroll:true});}
function openModal(type){modal=type;if(type==='example'||type==='help'){s.support??=[];s.support.push({kind:type,chapter:s.chapter,sub:s.sub,variant:s.variant,at:new Date().toISOString()});save();}helpStep=0;clearInterval(helpTimer);document.querySelector('#modal-body').innerHTML=modalContent();document.querySelector('#modal').showModal();}
function closeModal(){clearInterval(helpTimer);helpTimer=null;document.querySelector('#modal').close();modal='';save();}
function modalContent(){if(modal==='map')return mapPanel(s);if(modal==='concepts')return `<h2>Your reflection concepts</h2>${s.completed.map(n=>`<article class="concept-review"><h3>${n}. ${LEARNING[n].concept}</h3><p>${LEARNING[n].why}</p></article>`).join('')}<p class="small">Recap acknowledgements record a Next click, not proof of understanding. Independent checks are listed in the learning record.</p>`;if(modal==='settings')return `<p class="kicker">MAKE YOURSELF COMFORTABLE</p><h2>Settings & accessibility</h2><label class="check"><input id="reduced" type="checkbox" ${s.settings.reduced?'checked':''}> Reduce motion</label><label class="check"><input id="large" type="checkbox" ${s.settings.large?'checked':''}> Larger text</label><label class="check"><input id="sound" type="checkbox" ${s.settings.sound?'checked':''}> Soft confirmation sounds</label><p>No sound is required. Use the optional precision controls and arrow keys instead of dragging. Viewer mirrors also have Fit buttons. E inspects the puzzle. The room camera is optional; precision work uses a fixed view.</p><p class="small">WebGL2 required. Progress is saved in this browser and origin. Download your record to keep a copy.</p>`;if(modal==='credits')return `<h2>Original game. Shared mathematics.</h2><p>Find Lumi · ${RELEASE}. Original procedural 3D rooms, characters, props, story, puzzle layouts and UI. Maya, Lumi and Pip are fictional.</p><p>Mathematical reference: <a href="https://www.edb.gov.hk/attachment/en/curriculum-development/kla/ma/res/STEM-example_Reflection_en.pdf" target="_blank" rel="noopener">EDB — The Shortest Path and Reflection</a>. Game adaptation; not an EDB endorsement.</p><p>Interaction references: <a href="https://education.theiet.org/primary/teaching-resources/how-to-make-a-periscope" target="_blank" rel="noopener">IET · periscope construction</a>; <a href="https://ucsmp.uchicago.edu/secondary/curriculum/geometry/demos/mini-golf/" target="_blank" rel="noopener">UCSMP · mini golf and billiards</a>; <a href="https://medienportal.siemens-stiftung.org/en/crafts-with-reflection-symmetry-106272" target="_blank" rel="noopener">Siemens Stiftung · folded symmetry</a>; <a href="https://www.sciencebuddies.org/teacher-resources/lesson-plans/mirror-maze-reflection" target="_blank" rel="noopener">Science Buddies · mirror maze</a>. Original adaptation, not copied levels or assets.</p><p>Three.js 0.187.0, MIT license. <a href="vendor/THREE-LICENSE.txt" target="_blank">License</a>. No external textures, character models, fonts or game assets are required.</p><p>Model: ideal plane mirrors, straight rays in a uniform medium and ideal point-ball bounces without spin. The viewer checks two finite mirror apertures and wall occlusion for its central horizontal viewing ray; the window uses the twice-reflected observer viewpoint. One-reflection tasks use a source and receiver on the same side of one flat mirror, with no obstacles. Dashed paths are proposals or constructions; solid tested rays obey reflection. The optional obstacle workshop grades a working light link rather than global shortest distance.</p>`;if(modal==='menu')return `<h2>Adventure paused</h2><p>Task ${s.chapter} of 6 · ${CHAPTERS[s.chapter-1][0]}</p><p>Your progress and first-attempt evidence are saved.</p><div class="menu-buttons">${button('Back to my task','close')}${button('Settings','settings','quiet')}${button('Museum map & visitor pass','map','quiet')}${button('Learning record','report','quiet')}${button('About the game','about','quiet')}${button('Start a new adventure','reset','quiet')}</div>`;if(modal==='reset')return `<h2>Start a new adventure?</h2><p>This clears this visit’s progress and evidence. Download your results first if you want to keep them.</p>${button('Keep my visit','close','quiet')}${button('Clear and restart','confirm-reset')}`;if(modal==='report'){const r=results(s);return `<h2>Your learning record</h2><p>${s.completed.length}/6 tasks complete. <b>Game goal:</b> ${has(s,'escaped')?'Maya and Lumi are outside together.':has(s,'reunited')?'Reunited; the exit is still ahead.':'Open the route to Lumi.'}</p><p>Completion and independent mastery are separate.</p><p><b>LO1:</b> ${r.rays}/4 first predictions correct. Target ≥3/4.<br><b>LO2:</b> ${r.routes}/3 first constructions correct. Target ≥2/3.</p><table><thead><tr><th>Check</th><th>First result</th></tr></thead><tbody>${['ray-0','ray-1','ray-2','ray-3','route-0','route-1','route-2'].map(k=>`<tr><td>${k.replace('ray','Reflection').replace('route','Construction')}</td><td>${s.records[k]?(s.records[k].correct?'Correct':'Not correct'):'Not attempted'}</td></tr>`).join('')}</tbody></table><p>${r.recovered} fresh recovery successes · ${r.guided} guided completions. First results are never overwritten.</p><p>${s.recapLog.filter(r=>!r.bonus).length}/6 learning recaps acknowledged. ${button('Review concepts','concepts','text')}</p><p>${s.support?.length||0} optional help, example or Hint records, logged separately. Download includes the original givens and submitted plans.</p><label for="reflection">Optional reflection: how did reflecting B help you find the bounce point?<textarea id="reflection" rows="3">${esc(s.reflection||'')}</textarea></label><div class="result-actions">${button('Download record','download')}${button('Return','close','quiet')}</div>`;}const n=methodType(),steps=LESSONS[n],[title,copy]=steps[Math.min(helpStep,steps.length-1)];return `<p class="kicker">${modal==='help'?'HELP':'WORKED EXAMPLE'} · YOUR CURRENT TASK IS PRESERVED</p><p>Find the route to Lumi, repair and use your pass, then leave together. Explore safely; Pip teaches each method and helps after mistakes.</p><h2>${title}</h2>${lessonSVG(n,helpStep)}<p>${copy}</p><div class="result-actions">${button('▶ Play steps','help-play','quiet')}${button('Pause','help-pause','quiet')}${button('Replay','help-replay','quiet')}${helpStep<steps.length-1?button('Next step','help-next','quiet'):''}${button('Back to my task','close')}</div>`;}
function showOutcome(){motionLabel='';const ok=s.result?.ok;busy=!s.settings.reduced&&(ok||['ray','shape'].includes(s.task.kind));refresh();world.demonstrate(()=>{if(ok)world.animateJourney(()=>{busy=false;render();});else{busy=false;render();}});}
function stopLesson(){clearInterval(lessonTimer);lessonTimer=null;}
function chime(){if(!s.settings.sound)return;try{audio??=new AudioContext();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.setValueAtTime(660,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(990,audio.currentTime+.15);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);osc.start();osc.stop(audio.currentTime+.32);}catch{}}
function act(a){
 if(busy&&['about','confirm-reset','resume','exit-bonus'].includes(a)){world.anim=null;world.effect=null;busy=false;}
 if(busy&&!['help','example','menu','settings','credits','report','concepts','map','reset','close','download'].includes(a)&&!a.startsWith('help-'))return;
 if(['help','example','settings','credits','menu','report','concepts','map','reset'].includes(a)){stopLesson();openModal(a);return;}
 if(a==='close'){closeModal();return;}
 if(a==='start'){s.screen='opening';refresh(true);return;}
 if(a==='begin-journey'){enter(s,1);refresh(true);return;}
 if(['insert-pass','reunite','leave-together'].includes(a)){if(performAction(s,a)){motionLabel=a==='insert-pass'?'The repaired pass opens the courtyard gate…':a==='reunite'?'Maya walks through to Lumi…':'Maya and Lumi leave together…';busy=!s.settings.reduced;refresh();world.animateJourney(()=>{busy=false;render();},a);}return;}
 if(a==='resume'){s.screen='game';refresh(true);return;}
 if(a==='confirm-reset'){const nextRun=(s.run||0)+1;s=initial();s.run=nextRun;notice='';stopLesson();refresh(true);return;}
 if(a==='about'){s.screen='about';refresh(true);return;}
 if(a==='bonus'){if(startBonus(s)){notice='';refresh(true);}return;}
 if(a==='exit-bonus'){s.bonus=false;s.screen='end';refresh(true);return;}
 if(a==='view'){s.inspection=!s.inspection;render();world.setView(s);return;}
 if(a==='lesson-next'){stopLesson();s.lesson++;render();return;}
 if(a==='lesson-back'){stopLesson();s.lesson--;render();return;}
 if(a==='lesson-replay'){stopLesson();s.lesson=0;render();return;}
 if(a==='lesson-play'){if(lessonTimer){stopLesson();return;}if(s.lesson===lessonSteps().length-1)s.lesson=0;render();lessonTimer=setInterval(()=>{s.lesson=Math.min(s.lesson+1,lessonSteps().length-1);if(s.lesson===lessonSteps().length-1)stopLesson();render();},4000);return;}
 if(a==='begin'){stopLesson();begin(s);notice='';refresh();return;}
 if(a==='submit'){
  if(!validInput(s)){notice=s.task.kind==='investigation'?'Trace a bounce that reaches B, then choose an explanation. Extra comparisons are optional. No attempt recorded.':s.task.kind==='viewer'?'Fit and turn both mirrors before looking. No attempt recorded.':s.task.kind==='network'?'Place at least two mirrors before testing. No attempt recorded.':s.task.kind==='route'?(isFinalConstruction(s)?'Your plan needs a chosen point, a straightedge and a marked intersection. No attempt recorded.':'Place B′, draw A–B′ and use Mark P for the line–mirror intersection. No attempt recorded.'):s.task.kind==='shape'?'Place all three pass-pattern partners before submitting. No attempt recorded.':'Move the control or aim on the floor before testing. No attempt recorded.';render();return;}
  submit(s);notice='';if(s.result.ok)chime();showOutcome();return;
 }
 if(a==='retry'){retry(s);notice='';refresh(true);return;}
 if(a==='guided'){guided(s);chime();showOutcome();return;}
 if(a==='advance'){advance(s);notice='';refresh(true);return;}
 if(a==='next'){if(continueJourney(s)){notice='';refresh(true);}return;}
 if(a==='explain-investigation'){if(explainInvestigation(s)){notice='';refresh();}return;}if(a==='back-investigation'){s.draft.explaining=false;notice='';render();return;}if(a.startsWith('candidate-')){s.draft.selected=Number(a.split('-')[1]);s.draft.lastTest=null;notice='';refresh();return;}
 if(a==='test-path'){
  const d=s.draft;if(d.selected==null)return;const known=d.tests.find(r=>r.index===d.selected);if(known)d.lastTest=d.selected;else trial(s,d.selected);notice='';busy=!s.settings.reduced;refresh();world.demonstrate(()=>{world.animateJourney(()=>{busy=false;render();});});return;
 }
 if(a.startsWith('install-')){const i=Number(a.split('-')[1]);s.draft.installed[i]=true;s.draft.selected=i;notice='';refresh();return;}
 if(a.startsWith('mirror-')){s.draft.selected=Number(a.split('-')[1]);render();world.update(s);return;}
 if(a==='add-mirror'){if(s.draft.mirrors.length<3){s.draft.mirrors.push({x:5,y:2,angle:0,placed:false});s.draft.selected=s.draft.mirrors.length-1;refresh();}return;}
 if(a==='turn-left'||a==='turn-right'){const m=s.draft.mirrors[s.draft.selected];m.angle=((m.angle+(a==='turn-left'?-5:5))%180+180)%180;m.placed=true;notice='';refresh();return;}
 if(a==='side-right'||a==='side-wrong'){s.draft.side=a==='side-right'?1:-1;s.draft.touched=true;notice='';refresh();return;}
 if(a.startsWith('piece-')){s.draft.selected=Number(a.split('-')[1]);render();world.update(s);return;}
 if(a==='construction-hint'){if(isFinalConstruction(s)&&s.phase==='play'){toggleConstructionHint(s);notice='';render();if(s.draft.hintOpen)document.querySelector('#construction-hint-panel')?.scrollIntoView({block:'nearest'});}return;}
 if(a==='mode-image'){s.draft.mode='image';render();return;}
 if(a==='intersect'||a==='mode-p'){if(!constructIntersection(s)){notice='Draw a line from A to your B′ across the mirror first. No attempt recorded.';render();return;}notice='';refresh();return;}
 if(a==='line'){if(!s.draft.imageTouched){notice='Place your reflected goal B′ first. No attempt recorded.';render();return;}s.draft.line=true;s.draft.intersection=false;s.draft.pTouched=false;s.draft.mode='image';notice='';refresh();return;}
 if(a==='art-star'||a==='art-flower'){s.choices.art=a.split('-')[1];render();return;}
 if(a.startsWith('help-')){const n=methodType(),steps=LESSONS[n];if(a==='help-play'){clearInterval(helpTimer);if(helpStep===steps.length-1)helpStep=0;helpTimer=setInterval(()=>{helpStep=Math.min(helpStep+1,steps.length-1);if(helpStep===steps.length-1)clearInterval(helpTimer);document.querySelector('#modal-body').innerHTML=modalContent();},4000);}if(a==='help-pause')clearInterval(helpTimer);if(a==='help-replay'){clearInterval(helpTimer);helpStep=0;}if(a==='help-next'){clearInterval(helpTimer);helpStep=Math.min(helpStep+1,steps.length-1);}document.querySelector('#modal-body').innerHTML=modalContent();return;}
 if(a==='download'){const data={game:'Find Lumi',version:RELEASE,LO1,LO2,result:results(s),records:s.records,history:s.history,journey:s.journey,gameGoal:{reunited:has(s,'reunited'),escaped:has(s,'escaped')},support:s.support||[],recapsAcknowledged:s.recapLog,concepts:LEARNING.slice(1).map((l,i)=>({task:i+1,concept:l.concept,completed:s.completed.includes(i+1)})),choices:s.choices,reflection:s.reflection||'',at:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='find-lumi-learning-record.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
ui.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action);});
function drawDraft(){save();if(!draftFrame)draftFrame=requestAnimationFrame(()=>{draftFrame=null;world.update(s);});const d=s.draft,t=s.task;let values={};if(t.kind==='viewer')values={rotation:d.angles[0],rotation2:d.angles[1]};if(t.kind==='ray')values={angle:d.angle};if(t.kind==='shape')values={'point-x':d.points[d.selected].x,'point-y':d.points[d.selected].y};if(t.kind==='network')values={'point-x':d.mirrors[d.selected].x,'point-y':d.mirrors[d.selected].y,'mirror-rotation':d.mirrors[d.selected].angle};if(t.kind==='route')values={'point-x':d.image.x,'point-y':d.image.y};
 for(const [id,v]of Object.entries(values)){const el=document.getElementById(id);if(el)el.value=v;const o=document.getElementById(id+'-output');if(o)o.textContent=Number(v).toFixed(id==='angle'?0:1)+(['rotation','rotation2','angle','mirror-rotation'].includes(id)?'°':'');}
 if(t.kind==='route'){const prompts=constructionPrompts(s),line=document.querySelector('[data-action=line]'),mark=document.querySelector('[data-action=intersect]'),point=document.querySelector('[data-action=mode-image]');if(point)point.textContent=prompts.place;if(line){line.textContent=prompts.line;line.classList.toggle('selected',d.line);line.classList.toggle('quiet',!d.line);}if(mark){mark.textContent=prompts.intersect;mark.classList.toggle('selected',d.intersection);mark.classList.toggle('quiet',!d.intersection);}if(!d.intersection)document.querySelector('.construction-readout')?.remove();const instruction=document.querySelector('.play-instruction');if(instruction)instruction.textContent=prompts.instruction;}const val=document.querySelector('#validation');if(val)val.textContent='';const status=document.querySelector('#viewer-status');if(status)status.textContent=viewerHint(t,d);const count=document.querySelector('#placed-count');if(count)count.textContent=t.kind==='shape'?`${d.parts?.filter(Boolean).length||0}/3 partners placed · chosen ${s.choices.art} pass`:`${d.mirrors.filter(m=>m.placed).length} mirrors placed · up to 3 allowed`;const angle=document.querySelector('#mirror-angle');if(angle)angle.textContent=d.mirrors[d.selected].angle.toFixed(1)+'°';
}
function pointChange(id,value){const d=s.draft,t=s.task;if(t.kind==='viewer'&&['rotation','rotation2'].includes(id)){const i=id==='rotation'?0:1;d.angles[i]=value;d.turned[i]=true;d.selected=i;}if(id==='angle'){d.angle=value;d.touched=true;}if(t.kind==='network'&&id==='mirror-rotation'){d.mirrors[d.selected].angle=value;d.mirrors[d.selected].placed=true;}
 if(id==='point-x'||id==='point-y'){const c=id==='point-x'?'x':'y';if(t.kind==='shape'){const q={...d.points[d.selected],[c]:value};d.points[d.selected]=snapPoint(q);d.parts??=[false,false,false];d.parts[d.selected]=true;}else if(t.kind==='network'){d.mirrors[d.selected][c]=value;d.mirrors[d.selected].placed=true;}else{setImage(s,{...d.image,[c]:value});}}notice='';drawDraft();}
ui.addEventListener('input',e=>{const el=e.target,id=el.id;if(['reduced','large','sound'].includes(id)){s.settings[id]=el.checked;document.body.classList.toggle(id,el.checked);save();if(s.screen==='game')world.setView(s);return;}if(id==='reflection'){s.reflection=el.value;save();return;}if(el.name==='path-reason'&&s.phase==='play'&&!busy){s.draft.reason=el.value;notice='';save();return;}if(s.phase!=='play'||busy)return;if(['rotation','rotation2','angle','point-x','point-y','mirror-rotation'].includes(id))pointChange(id,Number(el.value));});
ui.addEventListener('dragstart',e=>{if(e.target.dataset.part!=null)e.dataTransfer.setData('text/plain',e.target.dataset.part);});const canvas=document.querySelector('#world');canvas.addEventListener('dragover',e=>{if(s.task?.kind==='viewer')e.preventDefault();});canvas.addEventListener('drop',e=>{if(s.task?.kind!=='viewer'||s.phase!=='play')return;e.preventDefault();const i=Number(e.dataTransfer.getData('text/plain'));if(i===0||i===1){s.draft.installed[i]=true;s.draft.selected=i;refresh();}});
function onPoint(p){if(s.screen!=='game'||s.phase!=='play'||busy)return;const t=s.task,d=s.draft;
 if(t.kind==='viewer'){d.selected=t.mirrors.reduce((best,m,i)=>Math.hypot(m.x-p.x,m.y-p.y)<Math.hypot(t.mirrors[best].x-p.x,t.mirrors[best].y-p.y)?i:best,0);return;}
 if(t.kind==='ray'){const old=d.side;let delta=((p.angle-(t.mirror-90)+540)%360)-180;d.angle=Math.min(85,Math.round(Math.abs(delta)));d.side=delta>=0?1:-1;d.touched=true;if(old!==d.side)render();}
 else if(t.kind==='shape'){d.points[d.selected]=snapPoint({x:Math.max(0,Math.min(10,p.x)),y:Math.max(-3.5,Math.min(3.5,p.y))});d.parts??=[false,false,false];d.parts[d.selected]=true;}
 else if(t.kind==='network'){const m=d.mirrors[d.selected];m.x=Math.max(.6,Math.min(9.4,Math.round(p.x*10)/10));m.y=Math.max(-3.5,Math.min(3.5,Math.round(p.y*10)/10));m.placed=true;}
 else if(t.kind==='investigation'){d.selected=t.candidates.reduce((best,x,i)=>Math.abs(x-p.x)<Math.abs(t.candidates[best]-p.x)?i:best,0);d.lastTest=null;render();}
 else if(t.kind==='route'){if(d.mode==='p'){if(Math.abs(p.y)<.6){constructIntersection(s);render();}return;}else{setImage(s,{x:Math.max(0,Math.min(10,p.x)),y:Math.max(-4,Math.min(4,p.y))});}}
 notice='';drawDraft();
}
try{world=new World(document.querySelector('#world'),onPoint,()=>{if(s.screen==='game'&&!s.inspection)act('view');});world.setup(s);}catch(e){console.error(e);document.querySelector('#fallback').hidden=false;}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopLesson();clearInterval(helpTimer);}});
render();
